{
  "thesis": "排行榜可以帮助研发负责人筛选值得内部测试的编程智能体，但不能直接证明生产提效。三项基准分别侧重仓库问题修复、较长流程与多仓库工程任务、带历史报酬的自由职业开发及方案选择，任务分布、执行配置和评分目标不同。2026年7月的质量质疑要求将判断下沉到题目、测试与版本，而非否定所有真实工程任务；采购应以配置可复现的结果初筛，再由真实私有仓库对照试点验证质量、人工投入和总成本。",
  "claims": [
    {
      "claim": "Verified是经人工筛选的500题子集，源于原SWE-bench的12个开源Python仓库，主要测量根据问题描述修改代码的能力。",
      "source": "swe-verified",
      "locator": "L53–60、L157–167",
      "qualification": "2024年8月13日发布，页面标注2025年2月24日更新；500题不是对所有语言和企业研发工作的代表性抽样，人工验证也不是永久质量保证。"
    },
    {
      "claim": "Verified要求补丁同时通过FAIL_TO_PASS和PASS_TO_PASS测试，并采用Docker容器化评测框架。",
      "source": "swe-verified",
      "locator": "L57–60、L162",
      "qualification": "代理看不到用于评分的测试；双组测试通过只是该测试体系下的解决判定，不能证明所有行为正确、没有安全问题或达到上线标准。"
    },
    {
      "claim": "Verified的原始修订针对过于特定的测试、需求描述不足和环境故障，说明低分也可能含有测量误差。",
      "source": "swe-verified",
      "locator": "L63–68、L155–160",
      "qualification": "这些是原始发布对旧题集问题及修订动机的说明，不应当作2026年Verified缺陷率的直接证据。"
    },
    {
      "claim": "Pro于2025年9月19日发布，包含1865题、41个仓库，分为731题公开集、858题留出集和276题商业集。",
      "source": "swe-pro",
      "locator": "全文字符0–7428；标题日期及“A Benchmark to Meet Today’s Coding Needs”",
      "qualification": "总体规模与公开榜单分母必须分开；公开、留出和商业子集的成绩不能混用。"
    },
    {
      "claim": "Pro扩大仓库与任务类型，由人工补充问题描述和行为要求，发布方报告平均修改107.4行、涉及4.1个文件。",
      "source": "swe-pro",
      "locator": "“Limited Task Diversity”及“Oversimplified Problems & Unrealistic Difficulty”",
      "qualification": "改动规模支持其较复杂任务定位，但不能单独证明难度、公平性或企业代表性；这些是发布方描述。"
    },
    {
      "claim": "Pro发布评测使用SWE-Agent；任务要求实现新功能测试且不破坏既有功能。",
      "source": "swe-pro；swe-noise",
      "locator": "Pro的“Results: SWE-Bench Verified vs. SWE-Bench Pro”；Noise L37",
      "qualification": "所给Pro原文在测试环境解决方案处没有具体内容，不能补写镜像、依赖、联网规则或重试配置；SWE-Agent是代理框架，不等同于执行环境说明。"
    },
    {
      "claim": "Pro将强copyleft公开代码和私有商业代码作为降低污染风险的设计措施。",
      "source": "swe-pro",
      "locator": "“Data Contamination”",
      "qualification": "强copyleft代码很可能被排除出训练是Scale的论据，并非已验证的训练数据事实；不能据此称整个基准绝无污染。"
    },
    {
      "claim": "SWE-Lancer于2025年2月18日发布，包含1400余项Upwork任务，历史实际报酬合计100万美元，同时涵盖独立开发和技术方案选择。",
      "source": "swe-lancer",
      "locator": "L13、L25–27",
      "qualification": "独立开发与管理选择是不同能力，不应合成无解释的编程解题率；历史报酬不是模型已取得的收入或企业可节省的成本。"
    },
    {
      "claim": "SWE-Lancer独立任务用经工程师三重验证的端到端测试评分，管理任务以原受聘经理的选择为参照；发布了统一Docker镜像和Diamond公开评测子集。",
      "source": "swe-lancer",
      "locator": "L26",
      "qualification": "测试验证不能保证覆盖全部需求；符合原经理选择并不证明该方案是唯一正确或经济最优方案。不得将全部任务数量直接视为Diamond题量。"
    },
    {
      "claim": "SWE-Lancer页面于2025年7月28日说明，数据与结果已更新至7月17日，并取消执行时的联网要求。",
      "source": "swe-lancer",
      "locator": "L30",
      "qualification": "联网依赖变化会改变表现波动来源；旧版和新版结果需要标明数据版本与执行规则，不能默认直接可比。"
    },
    {
      "claim": "2026年7月8日OpenAI对Pro公开集提出约30%题目有破坏性问题的估计，并撤回此前推荐。",
      "source": "swe-noise",
      "locator": "L13、L38–50、L74",
      "qualification": "这是OpenAI发表的审计结论，不是双方共同确认的结论；没有提供Scale对此的答复，不能虚构回应，也不能把估计外推到商业集。"
    },
    {
      "claim": "审计先筛出286个疑似问题，再深入复核；代理辅助路径判定200题，人类标注判定249题，分别占731题的27.4%和34.1%。",
      "source": "swe-noise",
      "locator": "L39–40、L55–66",
      "qualification": "五名工程师分别检查被筛出的题目；这不是对全体731题逐题进行相同人工审查，也不是随机抽样所得置信区间。两种路径共享疑似题筛选，不能当作完全独立复制。"
    },
    {
      "claim": "四类问题分别是测试过严、提示缺项、测试覆盖不足及提示误导，会同时造成假失败和假成功。",
      "source": "swe-noise",
      "locator": "L42–49、L71–72",
      "qualification": "不能按约30%的比例统一上调或下调成绩，也不能假定所有模型受到相同影响；修复方向是补齐行为约定、接受等价实现、增加覆盖并消除冲突。"
    },
    {
      "claim": "OpenAI在7月文章中还表示Verified存在设计和污染问题，已不再提供有意义的软件开发能力信号。",
      "source": "swe-noise",
      "locator": "L36",
      "qualification": "所给材料只包含该判断的转述，没有其链接调查全文；须归属于OpenAI，不能独立断言已复核污染范围或具体发生率。"
    },
    {
      "claim": "Pro公开集从23.3%升至80.3%的报道，不能单独证明生产效率同步提升。",
      "source": "swe-noise；swe-pro",
      "locator": "Noise L38；Pro的发布结果及按语言、仓库分层结果",
      "qualification": "八个月分数变化是来源报告；缺少逐次模型、框架、预算及版本控制信息，不应全部归因于模型能力提升，更不应把增长全部归因于题目缺陷。"
    },
    {
      "claim": "解题率按题数计量，奖金价值按历史金额加权，生产收益则还取决于审查、返工、运行成本和交付风险。",
      "source": "swe-verified；swe-lancer；作者分析",
      "locator": "Verified L60；Lancer L25–27",
      "qualification": "前两者计量差异由来源定义支持；生产收益的成本拆解属于采购分析。可用假设的高价少量题与低价大量题说明排序可能反转，但不虚构实测收益。"
    },
    {
      "claim": "最合理的采购证据链是同配置初筛、题目质量复核、内部仓库对照试点和有限范围扩展。",
      "source": "作者建议；swe-pro",
      "locator": "Pro的“What SWE-Bench Pro Results Mean”强调内部仓库表现及人工监督",
      "qualification": "具体流程和试点参数是建议，不是已测有效方案；不推荐未有内部实测支持的模型品牌，不把任何阈值写成行业标准。"
    }
  ],
  "counterevidence": [
    {
      "point": "三项基准具有真实任务来源，Verified有人审，Pro有人类补充要求，Lancer有多重测试验证。",
      "implication": "不能简单称其都是无用的玩具任务；同时，真实来源和人工检查都不能自动保证题意、参考补丁与评分一致。"
    },
    {
      "point": "Pro发布结果随语言、仓库和公开／商业子集显著变化。",
      "implication": "总分仍可提示需要测试的任务范围，但不应代替本公司技术栈的分层表现。商业子集较低也不能单独识别污染、难度或仓库差异各自的作用。"
    },
    {
      "point": "7月审计由模型开发商OpenAI发布；存在具体方法和数字，但没有另一方答复与完整跨机构复核。",
      "implication": "认真处理可检查的缺陷机制，同时保留审计归属和范围；不能因为发布者有利益关系就忽略证据，也不能写成无争议定论。"
    },
    {
      "point": "需求含糊本身可以是真实开发工作的一部分。",
      "implication": "应区分可由仓库惯例推断或通过澄清解决的含糊，与隐藏测试要求不可知信息的不公平；内部试点应允许受控澄清，并记录其人工成本。"
    },
    {
      "point": "去掉疑似问题题目会改变任务分布，评分修订也会使历史榜单失去直接可比性。",
      "implication": "不能只删失败题来提高分数；应先盲审定规则，冻结修订版，对候选系统统一重跑，分别报告原版与修订版结果及剔除原因。"
    }
  ],
  "parts": [
    {
      "number": 1,
      "headings": [
        "# 编程智能体排行榜能支持什么采购判断？",
        "## 判断摘要：用榜单筛选，不用榜单承诺提效",
        "## 三种基准测量的不是同一件事",
        "## 解题率、奖金价值与生产收益为何不能互换"
      ],
      "target_nonspace_characters": 1700,
      "coverage": [
        "用约180字符提出采购结论，并说明证据时间截至2026年10月13日。",
        "以紧凑对比呈现Verified、Pro、Lancer的研究对象、构成、执行框架或环境、评分方式与版本；Pro环境细节缺失明确保留。",
        "区分模型与代理系统，说明模型版本、框架、工具权限、预算、尝试次数及数据版本共同界定一个可比较结果。",
        "解释按题计数与历史金额加权的差别，强调方案选择不是代码交付，测试成功不等于可上线，历史奖金不等于净节省。",
        "就地引用原始发布；不用发布时模型分数推荐品牌，不设置资料清单。"
      ],
      "citation_plan": "Verified、Pro、Lancer的事实各在对应段落引用原始页面；引文以简短标题链接呈现，链接和Markdown均计入长度预算。"
    },
    {
      "number": 2,
      "headings": [
        "## 2026年7月质疑改变了哪些判断",
        "## 从初筛到真实仓库试点",
        "## 采购与扩展的条件"
      ],
      "target_nonspace_characters": 1900,
      "coverage": [
        "交代Pro审计的731题分母、286题筛选、200／249题判定及约30%估计的边界；归属OpenAI，不虚构Scale答复。",
        "用四类缺陷解释假失败与假成功，并逐项对应需求补充、等价实现测试、覆盖补强、提示冲突修复；明确不否定所有真实任务。",
        "将Verified原始结果降为历史背景，将未经复核的Pro总分降为待验证线索；Lancer可提示任务和报酬加权差异，但未受本次审计不等于已获无缺陷证明。",
        "采购初筛要求供应方提供题集版本、框架与模型版本、执行配置、单次及重试结果、成本和失败轨迹；缺少可复现记录的排名不作为采购承诺依据。",
        "提出4–6周、40–60项未公开内部任务的起始试点建议，注明这是可行性规模而非统计充分性保证；按语言、仓库和难度分层，兼顾修复、功能、跨文件改动与回归。",
        "设置纯人工与代理辅助对照，在难度匹配任务间随机分配并平衡开发者经验，避免同一人员重复同题的学习效应；任务开始前冻结验收标准与隐藏测试，独立维护者盲审。",
        "限定隔离环境、最小权限和合成数据，允许记录化需求澄清；保存版本、时间、成本、补丁和轨迹，禁止直接合并或接触生产凭据。",
        "计入所有分配任务与失败，报告验收率、返工、人工活跃时间、交付时长、调用成本及上线后回归；以人工基线校准扩展门槛，发生安全越权即暂停调查。",
        "仅在质量不劣、总成本改善且效果在目标任务层稳定时扩大范围；收益不确定时追加样本，不承诺整体研发效率提升。"
      ],
      "citation_plan": "审计数字和Verified后续判断集中就地引用7月原文，Pro任务分层差异引用Scale发布。试点明确标为建议，避免用文献引用伪装成已验证效果。"
    }
  ]
}
